css:
.levels {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  padding: 32px;
  background-color: #f4f4f5;
  font-family: system-ui, sans-serif;
}

.card {
  display: grid;
  place-items: center;
  height: 100px;
  border-radius: 10px;
  background-color: #ffffff;
  font-weight: 600;
}

.low {
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.15);
}

.mid {
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.12), 0 6px 16px rgb(0 0 0 / 0.1);
}

.high {
  box-shadow: 0 2px 4px rgb(0 0 0 / 0.1), 0 20px 40px rgb(0 0 0 / 0.18);
}
